import { defineComponentUsageCode } from "@/i18n/component-usage-code";

export const componentUsageCodeEn = defineComponentUsageCode({
"image-card": "export default function Example() {\n    const image = {\n        \"alt\": \"Workspace cover with a soft blue gradient\",\n        \"caption\": \"Design system workspace · 12 components\"\n    };\n    const previewImage = \"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 4 3'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' x2='1'%3E%3Cstop stop-color='%23dbeafe'/%3E%3Cstop offset='1' stop-color='%23bfdbfe'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='4' height='3' fill='url(%23g)'/%3E%3C/svg%3E\";\n    return <ImageCard src={previewImage} alt={image.alt} caption={image.caption} className=\"max-w-xs\"/>;\n}",
"marquee": "export default function Example() {\n    const marquee = {\n        \"items\": [\n            \"Accessibility\",\n            \"Base UI\",\n            \"React 19\",\n            \"Tailwind 4\"\n        ],\n        \"label\": \"Supported technologies\",\n        \"pause\": \"Pause animation\",\n        \"resume\": \"Resume animation\"\n    };\n    return <Marquee items={marquee.items} label={marquee.label} pauseLabel={marquee.pause} resumeLabel={marquee.resume} duration={18}/>;\n}",
"sidebar": "export default function Example() {\n    const text = {\n        \"close\": \"Close\"\n    };\n    const sidebar = {\n        \"workspace\": \"Workspace\",\n        \"navigation\": \"Navigation\",\n        \"overview\": \"Overview\",\n        \"settings\": \"Settings\",\n        \"toggle\": \"Toggle sidebar\",\n        \"body\": \"Review the most important information for the current project.\"\n    };\n    return <SidebarProvider className=\"h-56 w-full max-w-lg overflow-hidden rounded-[var(--neu-radius-surface)] border border-[color:var(--neu-edge)] [box-shadow:var(--neu-shadow-inset)]\"><Sidebar collapsible=\"icon\" mobileTitle={sidebar.workspace} mobileDescription={sidebar.navigation} closeLabel={text.close}><SidebarHeader><strong className=\"truncate text-sm\">{sidebar.workspace}</strong></SidebarHeader><SidebarContent><SidebarGroup><SidebarGroupLabel>{sidebar.navigation}</SidebarGroupLabel><SidebarGroupContent><SidebarMenu><SidebarMenuItem><SidebarMenuButton isActive tooltip={sidebar.overview}><svg aria-hidden=\"true\" className=\"size-4 shrink-0\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"m3 10 9-7 9 7v10H3Z\"/><path d=\"M9 20v-7h6v7\"/></svg><span>{sidebar.overview}</span></SidebarMenuButton></SidebarMenuItem><SidebarMenuItem><SidebarMenuButton tooltip={sidebar.settings}><svg aria-hidden=\"true\" className=\"size-4 shrink-0\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg><span>{sidebar.settings}</span></SidebarMenuButton></SidebarMenuItem></SidebarMenu></SidebarGroupContent></SidebarGroup></SidebarContent></Sidebar><SidebarInset><header className=\"flex items-center gap-2 border-b border-[var(--border)] p-2\"><SidebarTrigger label={sidebar.toggle}/><strong className=\"text-sm\">{sidebar.overview}</strong></header><div className=\"p-4 text-sm text-[var(--muted-foreground)]\">{sidebar.body}</div></SidebarInset></SidebarProvider>;\n}",
"carousel": "export default function Example() {\n  return <Carousel aria-label=\"Feature tour\" className=\"w-full max-w-md px-12\">\n    <CarouselContent>\n      {[\"Dashboard\", \"Settings\", \"Analytics\"].map((item) => <CarouselItem key={item}><div className=\"p-2\"><div className=\"grid h-40 place-items-center rounded-[var(--neu-radius-surface)] border border-[var(--neu-edge)] bg-[var(--neu-surface)] [box-shadow:var(--neu-shadow-raised-sm)]\">{item}</div></div></CarouselItem>)}\n    </CarouselContent>\n    <CarouselPrevious />\n    <CarouselNext />\n  </Carousel>;\n}",
"resizable": "export default function Example() {\n  return <div className=\"h-48 max-w-lg\"><ResizablePanelGroup orientation=\"horizontal\">\n    <ResizablePanel defaultSize=\"40%\" minSize=\"25%\"><div className=\"grid h-full place-items-center p-4\">List</div></ResizablePanel>\n    <ResizableHandle withHandle />\n    <ResizablePanel defaultSize=\"60%\" minSize=\"30%\"><div className=\"grid h-full place-items-center p-4\">Details</div></ResizablePanel>\n  </ResizablePanelGroup></div>;\n}",
"input-otp": "export default function Example() {\n    const locale = \"en\";\n    const otpCopy = {\n        \"ko\": \"인증 코드\",\n        \"en\": \"Verification code\",\n        \"ja\": \"認証コード\",\n        \"zh\": \"验证码\"\n    };\n    return <div className=\"grid gap-3\"><InputOTP maxLength={6} aria-label={otpCopy[locale]}><InputOTPGroup><InputOTPSlot index={0}/><InputOTPSlot index={1}/><InputOTPSlot index={2}/></InputOTPGroup><InputOTPSeparator /><InputOTPGroup><InputOTPSlot index={3}/><InputOTPSlot index={4}/><InputOTPSlot index={5}/></InputOTPGroup></InputOTP></div>;\n}",
"drawer": "export default function Example() {\n  return <Drawer swipeDirection=\"down\">\n    <DrawerTrigger render={<Button />}>Quick settings</DrawerTrigger>\n    <DrawerContent>\n      <DrawerHeader>\n        <DrawerTitle>Quick settings</DrawerTitle>\n        <DrawerDescription>Adjust frequent options without leaving the current screen.</DrawerDescription>\n      </DrawerHeader>\n      <div className=\"grid gap-3 px-5 py-4\"><p>Notification and display controls can live in this area.</p></div>\n      <DrawerFooter><DrawerClose render={<Button variant=\"primary\" />}>Done</DrawerClose></DrawerFooter>\n    </DrawerContent>\n  </Drawer>;\n}",
"context-menu": "export default function Example() {\n    const text = {\n        \"tools\": \"Document tools\",\n        \"undo\": \"Undo\",\n        \"details\": \"Advanced settings\",\n        \"quiet\": \"Saved state\"\n    };\n    const [message, setMessage] = React.useState(\"\");\n    const [expanded, setExpanded] = React.useState(false);\n    return <div className=\"grid w-full max-w-sm gap-3\"><ContextMenu><ContextMenuTrigger className=\"grid min-h-32 place-items-center rounded-[var(--neu-radius-surface)] border border-[color:var(--neu-edge)] bg-[var(--neu-surface)] p-5 text-center text-sm font-medium [box-shadow:var(--neu-shadow-inset)]\">{text.tools}</ContextMenuTrigger><ContextMenuContent><ContextMenuLabel>{text.tools}</ContextMenuLabel><ContextMenuItem onClick={() => setMessage(text.undo)}>{text.undo}<ContextMenuShortcut>⌘Z</ContextMenuShortcut></ContextMenuItem><ContextMenuCheckboxItem checked={expanded} onCheckedChange={setExpanded}>{text.details}</ContextMenuCheckboxItem></ContextMenuContent></ContextMenu><p role=\"status\" className=\"text-sm text-[var(--muted-foreground)]\">{message || text.quiet}</p></div>;\n}",
"command": "export default function Example() {\n    const text = {\n        \"city\": \"Search cities\",\n        \"empty\": \"No matching cities.\",\n        \"quiet\": \"Saved state\"\n    };\n    const cities = [\"Busan\", \"London\", \"Seoul\", \"Tokyo\"];\n    const [message, setMessage] = React.useState(\"\");\n    return <div className=\"grid w-full max-w-sm gap-3\"><Command><CommandInput placeholder={text.city} aria-label={text.city}/><CommandList><CommandEmpty>{text.empty}</CommandEmpty><CommandGroup heading={text.city}>{cities.map((city, index) => <CommandItem key={city} value={city} onSelect={() => setMessage(city)}>{city}<CommandShortcut>⌘{index + 1}</CommandShortcut></CommandItem>)}</CommandGroup></CommandList></Command><p role=\"status\" className=\"text-sm text-[var(--muted-foreground)]\">{message || text.quiet}</p></div>;\n}",
"chart": "export default function Example() {\n  const data = [{ date: \"09-01\", visits: 140 }, { date: \"09-02\", visits: 220 }, { date: \"09-03\", visits: 175 }];\n  return <ChartContainer title=\"Daily visits\" description=\"Illustrative data. Exact values are available in the table.\" tableLabel=\"View data\" table={<table><caption>Daily visits</caption><thead><tr><th scope=\"col\">Date</th><th scope=\"col\">Visits</th></tr></thead><tbody>{data.map(row => <tr key={row.date}><th scope=\"row\">{row.date}</th><td>{row.visits}</td></tr>)}</tbody></table>}>\n    <BarChart data={data} accessibilityLayer><XAxis dataKey=\"date\" /><ChartTooltip /><Bar dataKey=\"visits\" name=\"Visits\" fill=\"var(--primary)\" isAnimationActive={false} /></BarChart>\n  </ChartContainer>;\n}",
"navigation-menu": "export default function Example() {\n    const t = {\n        \"product\": \"Product\",\n        \"components\": \"Components\",\n        \"themes\": \"Themes\",\n        \"guides\": \"Guides\",\n        \"guideText\": \"Choose a destination from the navigation menu.\"\n    };\n    const id = React.useId();\n    const componentCount = 56;\n    return <div className=\"grid w-full gap-5\"><NavigationMenu aria-label={t.product}><NavigationMenuList><NavigationMenuItem><NavigationMenuTrigger>{t.product}</NavigationMenuTrigger><NavigationMenuContent><NavigationMenuLink href={`#${id}-components`}>{t.components}</NavigationMenuLink><NavigationMenuLink href={`#${id}-themes`}>{t.themes}</NavigationMenuLink></NavigationMenuContent></NavigationMenuItem><NavigationMenuItem><NavigationMenuLink href={`#${id}-guide`}>{t.guides}</NavigationMenuLink></NavigationMenuItem></NavigationMenuList><NavigationMenuViewport /></NavigationMenu><div className=\"grid gap-2 text-sm text-[var(--muted-foreground)] [&>p[id]]:scroll-mt-24\"><p id={`${id}-guide`}>{t.guideText}</p><p id={`${id}-components`}>{t.components} · {componentCount}</p><p id={`${id}-themes`}>{t.themes} · 5</p></div></div>;\n}",
"menubar": "export default function Example() {\n    const t = {\n        \"file\": \"File\",\n        \"create\": \"New document\",\n        \"archived\": \"Archive\",\n        \"view\": \"View\",\n        \"status\": \"Show status\",\n        \"created\": \"New document created\",\n        \"ready\": \"Ready\"\n    };\n    const [showStatus, setShowStatus] = React.useState(true);\n    const [created, setCreated] = React.useState(false);\n    return <div className=\"grid w-full gap-4\"><Menubar aria-label={t.file}><MenubarMenu><MenubarTrigger>{t.file}</MenubarTrigger><MenubarContent><MenubarItem onClick={() => setCreated(true)}>{t.create}</MenubarItem><MenubarItem disabled>{t.archived}</MenubarItem></MenubarContent></MenubarMenu><MenubarMenu><MenubarTrigger>{t.view}</MenubarTrigger><MenubarContent><MenubarCheckboxItem checked={showStatus} onCheckedChange={setShowStatus}>{t.status}</MenubarCheckboxItem></MenubarContent></MenubarMenu></Menubar>{showStatus && <p role=\"status\" className=\"text-sm text-[var(--muted-foreground)]\">{created ? t.created : t.ready}</p>}</div>;\n}",
  accordion: "export default function Example() {\n    const copy = {\n        \"accordion\": {\n            \"items\": [\n                {\n                    \"question\": \"Are the style tokens installed too?\",\n                    \"answer\": \"Install the shared base once first. It connects the neumorphic surface, shadow, and radius tokens to your project CSS for components to use.\"\n                },\n                {\n                    \"question\": \"Can I edit the source after installation?\",\n                    \"answer\": \"Yes. The actual TSX files are copied into your project instead of being hidden inside a package.\"\n                },\n                {\n                    \"question\": \"Does it support keyboard controls?\",\n                    \"answer\": \"Use Tab to reach a trigger, then press Enter or Space to open its content.\"\n                }\n            ]\n        }\n    };\n    return (<div className=\"mx-auto w-full max-w-[620px]\">\n          <Accordion defaultValue={[\"tokens\"]}>\n            <AccordionItem value=\"tokens\">\n              <AccordionTrigger>\n                {copy.accordion.items[0].question}\n              </AccordionTrigger>\n              <AccordionContent>\n                {copy.accordion.items[0].answer}\n              </AccordionContent>\n            </AccordionItem>\n            <AccordionItem value=\"source\">\n              <AccordionTrigger>\n                {copy.accordion.items[1].question}\n              </AccordionTrigger>\n              <AccordionContent>\n                {copy.accordion.items[1].answer}\n              </AccordionContent>\n            </AccordionItem>\n            <AccordionItem value=\"keyboard\">\n              <AccordionTrigger>\n                {copy.accordion.items[2].question}\n              </AccordionTrigger>\n              <AccordionContent>\n                {copy.accordion.items[2].answer}\n              </AccordionContent>\n            </AccordionItem>\n          </Accordion>\n        </div>);\n}",
  alert: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"alert\": {\n            \"newVersion\": \"New Registry version\",\n            \"newVersionBody\": \"Reinstall the local source to review the changes.\",\n            \"synced\": \"Sync complete\",\n            \"syncedBody\": \"All 56 components match the current project.\",\n            \"missingTokens\": \"Tokens not found\",\n            \"missingTokensBody\": \"Install the base item in globals.css first.\"\n        }\n    };\n    return (<PreviewStack>\n          <Alert>\n            <svg aria-hidden=\"true\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 11v6M12 7h.01\"/></svg>\n            <AlertTitle>{copy.alert.newVersion}</AlertTitle>\n            <AlertDescription>{copy.alert.newVersionBody}</AlertDescription>\n          </Alert>\n          <Alert variant=\"success\">\n            <svg aria-hidden=\"true\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"m5 12 4 4L19 6\"/></svg>\n            <AlertTitle>{copy.alert.synced}</AlertTitle>\n            <AlertDescription>{copy.alert.syncedBody}</AlertDescription>\n          </Alert>\n          <Alert variant=\"destructive\">\n            <svg aria-hidden=\"true\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v6M12 17h.01\"/></svg>\n            <AlertTitle>{copy.alert.missingTokens}</AlertTitle>\n            <AlertDescription>{copy.alert.missingTokensBody}</AlertDescription>\n          </Alert>\n        </PreviewStack>);\n}",
  avatar: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"avatar\": {\n            \"team\": \"Team\"\n        }\n    };\n    return (<PreviewStack compact>\n          <div className=\"flex items-center gap-3\">\n            <Avatar size=\"sm\">\n              <AvatarFallback>SM</AvatarFallback>\n            </Avatar>\n            <Avatar>\n              <AvatarFallback>AM</AvatarFallback>\n              <AvatarBadge />\n            </Avatar>\n            <Avatar size=\"lg\">\n              <AvatarFallback>UI</AvatarFallback>\n              <AvatarBadge />\n            </Avatar>\n          </div>\n          <div className=\"flex flex-wrap items-center justify-between gap-8 p-4\">\n            <span className=\"text-sm font-medium text-[var(--muted-foreground)]\">{copy.avatar.team}</span>\n            <AvatarGroup>\n              <Avatar><AvatarFallback>AN</AvatarFallback></Avatar>\n              <Avatar><AvatarFallback>DE</AvatarFallback></Avatar>\n              <Avatar><AvatarFallback>SO</AvatarFallback></Avatar>\n              <AvatarGroupCount>+9</AvatarGroupCount>\n            </AvatarGroup>\n          </div>\n        </PreviewStack>);\n}",
  badge: "export default function Example() {\n    return (<div className=\"flex items-center gap-3 flex-wrap justify-center\">\n          <Badge>Default</Badge>\n          <Badge variant=\"primary\">Primary</Badge>\n          <Badge variant=\"soft\">Soft</Badge>\n          <Badge variant=\"outline\">Outline</Badge>\n          <Badge variant=\"destructive\">Destructive</Badge>\n        </div>);\n}",
  breadcrumb: "export default function Example() {\n    const copy = {\n        \"breadcrumb\": {\n            \"label\": \"Breadcrumb\"\n        }\n    };\n    return (<Breadcrumb aria-label={copy.breadcrumb.label}>\n          <BreadcrumbList>\n            <BreadcrumbItem>\n              <BreadcrumbLink href={\"/components\"}>\n                Components\n              </BreadcrumbLink>\n            </BreadcrumbItem>\n            <BreadcrumbItem>\n              <BreadcrumbSeparator />\n              <BreadcrumbEllipsis />\n            </BreadcrumbItem>\n            <BreadcrumbItem>\n              <BreadcrumbSeparator />\n              <BreadcrumbLink href={\"/components\"}>\n                Navigation\n              </BreadcrumbLink>\n            </BreadcrumbItem>\n            <BreadcrumbItem>\n              <BreadcrumbSeparator />\n              <BreadcrumbPage>Breadcrumb</BreadcrumbPage>\n            </BreadcrumbItem>\n          </BreadcrumbList>\n        </Breadcrumb>);\n}",
  button: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"button\": {\n            \"delete\": \"Delete\",\n            \"small\": \"Small\",\n            \"large\": \"Large\",\n            \"addItem\": \"Add item\",\n            \"disabled\": \"Disabled\"\n        }\n    };\n    return (<PreviewStack>\n          <div className=\"flex items-center gap-3 flex-wrap justify-center\">\n            <Button>Default</Button>\n            <Button variant=\"primary\">Primary</Button>\n            <Button variant=\"soft\">Soft</Button>\n            <Button variant=\"ghost\">Ghost</Button>\n            <Button variant=\"destructive\">{copy.button.delete}</Button>\n          </div>\n          <div className=\"flex items-center gap-3 flex-wrap justify-center\">\n            <Button size=\"sm\">{copy.button.small}</Button>\n            <Button>Default</Button>\n            <Button size=\"lg\">{copy.button.large}</Button>\n            <Button size=\"icon\" aria-label={copy.button.addItem}><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"M5 12h14M12 5v14\"/></svg></Button>\n            <Button disabled>{copy.button.disabled}</Button>\n          </div>\n        </PreviewStack>);\n}",
  card: "export default function Example() {\n    const copy = {\n        \"card\": {\n            \"marketOverview\": \"Market overview\",\n            \"marketOverviewBody\": \"See today's watchlist movement at a glance.\",\n            \"live\": \"Live\",\n            \"details\": \"View details\",\n            \"insetSurface\": \"Inset surface\",\n            \"insetSurfaceBody\": \"Use recessed depth for supporting information.\",\n            \"portfolioTarget\": \"Portfolio target\"\n        }\n    };\n    return (<div className=\"grid gap-5 sm:grid-cols-2\">\n          <Card className=\"min-w-0\">\n            <CardHeader>\n              <CardTitle>{copy.card.marketOverview}</CardTitle>\n              <CardDescription>{copy.card.marketOverviewBody}</CardDescription>\n              <CardAction>\n                <Badge variant=\"primary\">{copy.card.live}</Badge>\n              </CardAction>\n            </CardHeader>\n            <CardContent>\n              <div className=\"flex items-baseline justify-between gap-4 [&_strong]:text-2xl [&_span]:text-[var(--success)]\">\n                <strong>₩72,400</strong>\n                <span>+2.41%</span>\n              </div>\n            </CardContent>\n            <CardFooter>\n              <Button variant=\"soft\" className=\"w-full\">\n                {copy.card.details}\n              </Button>\n            </CardFooter>\n          </Card>\n          <Card className=\"min-w-0\" variant=\"inset\">\n            <CardHeader>\n              <CardTitle>{copy.card.insetSurface}</CardTitle>\n              <CardDescription>{copy.card.insetSurfaceBody}</CardDescription>\n            </CardHeader>\n            <CardContent>\n              <Progress aria-label={copy.card.portfolioTarget} value={68}/>\n            </CardContent>\n          </Card>\n        </div>);\n}",
  checkbox: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nexport default function Example() {\n    const [mixed, setMixed] = React.useState<CheckedState>(\"indeterminate\");\n    const copy = {\n        \"checkbox\": {\n            \"priceAlerts\": \"Receive price alerts\",\n            \"partialWorkspace\": \"Applied to some workspaces\",\n            \"unavailable\": \"Unavailable option\"\n        }\n    };\n    return (<PreviewStack compact>\n          <Label className=\"inline-flex w-fit cursor-pointer items-center gap-2.5 text-sm\" htmlFor=\"docs-checkbox-checked\">\n            <Checkbox id=\"docs-checkbox-checked\" defaultChecked/>\n            {copy.checkbox.priceAlerts}\n          </Label>\n          <Label className=\"inline-flex w-fit cursor-pointer items-center gap-2.5 text-sm\" htmlFor=\"docs-checkbox-mixed\">\n            <Checkbox id=\"docs-checkbox-mixed\" checked={mixed} onCheckedChange={setMixed}/>\n            {copy.checkbox.partialWorkspace}\n          </Label>\n          <Label className=\"inline-flex w-fit cursor-pointer items-center gap-2.5 text-sm\" htmlFor=\"docs-checkbox-disabled\">\n            <Checkbox id=\"docs-checkbox-disabled\" disabled/>\n            {copy.checkbox.unavailable}\n          </Label>\n        </PreviewStack>);\n}",
  dialog: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nfunction PreviewField({ children, htmlFor, label }: {\n    children: React.ReactNode;\n    htmlFor?: string;\n    label: string;\n}) {\n    return <div className=\"grid gap-2\">{htmlFor ? <Label htmlFor={htmlFor}>{label}</Label> : <span className=\"text-sm font-medium\">{label}</span>}{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"dialog\": {\n            \"editProfile\": \"Edit profile\",\n            \"description\": \"Change the name and handle shown on your public profile.\",\n            \"name\": \"Name\",\n            \"username\": \"Username\",\n            \"cancel\": \"Cancel\",\n            \"save\": \"Save\",\n            \"hint\": \"Open it to test the focus trap and Escape-to-close behavior.\"\n        }\n    };\n    return (<div className=\"flex items-center gap-3\">\n          <Dialog>\n            <DialogTrigger render={<Button variant=\"primary\"/>}>\n              {copy.dialog.editProfile}\n            </DialogTrigger>\n            <DialogContent showCloseButton={false}>\n              <DialogHeader>\n                <DialogTitle>{copy.dialog.editProfile}</DialogTitle>\n                <DialogDescription>{copy.dialog.description}</DialogDescription>\n              </DialogHeader>\n              <PreviewStack compact>\n                <PreviewField htmlFor=\"docs-dialog-name\" label={copy.dialog.name}>\n                  <Input defaultValue=\"Andongmin\" id=\"docs-dialog-name\"/>\n                </PreviewField>\n                <PreviewField htmlFor=\"docs-dialog-username\" label={copy.dialog.username}>\n                  <Input defaultValue=\"@softsurface\" id=\"docs-dialog-username\"/>\n                </PreviewField>\n              </PreviewStack>\n              <DialogFooter>\n                <DialogClose render={<Button variant=\"soft\"/>}>\n                  {copy.dialog.cancel}\n                </DialogClose>\n                <DialogClose render={<Button variant=\"primary\"/>}>\n                  {copy.dialog.save}\n                </DialogClose>\n              </DialogFooter>\n            </DialogContent>\n          </Dialog>\n          <span className=\"text-xs text-[var(--muted-foreground)]\">{copy.dialog.hint}</span>\n        </div>);\n}",
  "dropdown-menu": "export default function Example() {\n    const [showDepthGrid, setShowDepthGrid] = React.useState(true);\n    const copy = {\n        \"dropdown\": {\n            \"workspaceMenu\": \"Workspace menu\",\n            \"workspace\": \"My workspace\",\n            \"newPage\": \"New page\",\n            \"duplicate\": \"Duplicate\",\n            \"showDepthGrid\": \"Show depth guides\",\n            \"theme\": \"Theme\",\n            \"light\": \"Light\",\n            \"dark\": \"Dark\",\n            \"system\": \"System\",\n            \"deleteWorkspace\": \"Delete workspace\"\n        }\n    };\n    return (<DropdownMenu>\n          <DropdownMenuTrigger render={<Button variant=\"soft\"/>}>\n            {copy.dropdown.workspaceMenu} <svg aria-hidden=\"true\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"m6 9 6 6 6-6\"/></svg>\n          </DropdownMenuTrigger>\n          <DropdownMenuContent align=\"start\">\n            <DropdownMenuGroup>\n              <DropdownMenuLabel>{copy.dropdown.workspace}</DropdownMenuLabel>\n              <DropdownMenuSeparator />\n              <DropdownMenuItem>\n                {copy.dropdown.newPage}{\" \"}\n                <DropdownMenuShortcut>⌘N</DropdownMenuShortcut>\n              </DropdownMenuItem>\n              <DropdownMenuItem>{copy.dropdown.duplicate}</DropdownMenuItem>\n              <DropdownMenuCheckboxItem checked={showDepthGrid} onCheckedChange={setShowDepthGrid}>\n                {copy.dropdown.showDepthGrid}\n              </DropdownMenuCheckboxItem>\n              <DropdownMenuSub>\n                <DropdownMenuSubTrigger>{copy.dropdown.theme}</DropdownMenuSubTrigger>\n                <DropdownMenuSubContent>\n                  <DropdownMenuRadioGroup defaultValue=\"system\">\n                    <DropdownMenuRadioItem value=\"light\">\n                      {copy.dropdown.light}\n                    </DropdownMenuRadioItem>\n                    <DropdownMenuRadioItem value=\"dark\">\n                      {copy.dropdown.dark}\n                    </DropdownMenuRadioItem>\n                    <DropdownMenuRadioItem value=\"system\">\n                      {copy.dropdown.system}\n                    </DropdownMenuRadioItem>\n                  </DropdownMenuRadioGroup>\n                </DropdownMenuSubContent>\n              </DropdownMenuSub>\n              <DropdownMenuSeparator />\n              <DropdownMenuItem variant=\"destructive\">\n                {copy.dropdown.deleteWorkspace}\n              </DropdownMenuItem>\n            </DropdownMenuGroup>\n          </DropdownMenuContent>\n        </DropdownMenu>);\n}",
  input: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nfunction PreviewField({ children, htmlFor, label }: {\n    children: React.ReactNode;\n    htmlFor?: string;\n    label: string;\n}) {\n    return <div className=\"grid gap-2\">{htmlFor ? <Label htmlFor={htmlFor}>{label}</Label> : <span className=\"text-sm font-medium\">{label}</span>}{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"input\": {\n            \"email\": \"Email\",\n            \"invalid\": \"Invalid\",\n            \"disabled\": \"Disabled\",\n            \"readOnlyWorkspace\": \"Read-only workspace\"\n        }\n    };\n    return (<PreviewStack>\n          <PreviewField htmlFor=\"docs-input-email\" label={copy.input.email}>\n            <Input id=\"docs-input-email\" type=\"email\" placeholder=\"you@example.com\"/>\n          </PreviewField>\n          <PreviewField htmlFor=\"docs-input-invalid\" label={copy.input.invalid}>\n            <Input aria-invalid defaultValue=\"wrong-address\" id=\"docs-input-invalid\"/>\n          </PreviewField>\n          <PreviewField htmlFor=\"docs-input-disabled\" label={copy.input.disabled}>\n            <Input defaultValue={copy.input.readOnlyWorkspace} disabled id=\"docs-input-disabled\"/>\n          </PreviewField>\n        </PreviewStack>);\n}",
  "input-group": "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nfunction PreviewField({ children, htmlFor, label }: {\n    children: React.ReactNode;\n    htmlFor?: string;\n    label: string;\n}) {\n    return <div className=\"grid gap-2\">{htmlFor ? <Label htmlFor={htmlFor}>{label}</Label> : <span className=\"text-sm font-medium\">{label}</span>}{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"inputGroup\": {\n            \"search\": \"Search\",\n            \"searchPlaceholder\": \"Search components...\",\n            \"website\": \"Website\",\n            \"message\": \"Message\",\n            \"messagePlaceholder\": \"Write a short note...\",\n            \"send\": \"Send\"\n        }\n    };\n    return (<PreviewStack>\n          <PreviewField htmlFor=\"docs-input-group-search\" label={copy.inputGroup.search}>\n            <InputGroup>\n              <InputGroupAddon aria-hidden=\"true\"><svg aria-hidden=\"true\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg></InputGroupAddon>\n              <InputGroupInput id=\"docs-input-group-search\" placeholder={copy.inputGroup.searchPlaceholder}/>\n              <InputGroupButton>{copy.inputGroup.search}</InputGroupButton>\n            </InputGroup>\n          </PreviewField>\n          <PreviewField htmlFor=\"docs-input-group-website\" label={copy.inputGroup.website}>\n            <InputGroup>\n              <InputGroupAddon><InputGroupText>https://</InputGroupText></InputGroupAddon>\n              <InputGroupInput defaultValue=\"neumorphism.local\" id=\"docs-input-group-website\"/>\n            </InputGroup>\n          </PreviewField>\n          <PreviewField htmlFor=\"docs-input-group-message\" label={copy.inputGroup.message}>\n            <InputGroup>\n              <InputGroupTextarea id=\"docs-input-group-message\" placeholder={copy.inputGroup.messagePlaceholder}/>\n              <InputGroupButton>{copy.inputGroup.send}</InputGroupButton>\n            </InputGroup>\n          </PreviewField>\n        </PreviewStack>);\n}",
  label: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nfunction PreviewField({ children, htmlFor, label }: {\n    children: React.ReactNode;\n    htmlFor?: string;\n    label: string;\n}) {\n    return <div className=\"grid gap-2\">{htmlFor ? <Label htmlFor={htmlFor}>{label}</Label> : <span className=\"text-sm font-medium\">{label}</span>}{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"label\": {\n            \"caption\": \"Clicking a label moves focus to its control.\",\n            \"email\": \"Email address\",\n            \"weeklyReport\": \"Receive the weekly report\"\n        }\n    };\n    return (<PreviewStack>\n          <PreviewField label={copy.label.caption}>\n            <Label htmlFor=\"docs-label-email\">{copy.label.email}</Label>\n            <Input id=\"docs-label-email\" type=\"email\" placeholder=\"name@company.com\"/>\n          </PreviewField>\n          <Label className=\"inline-flex w-fit cursor-pointer items-center gap-2.5 text-sm\" htmlFor=\"docs-label-switch\">\n            <Switch id=\"docs-label-switch\" defaultChecked/>\n            {copy.label.weeklyReport}\n          </Label>\n        </PreviewStack>);\n}",
  pagination: "export default function Example() {\n    const [paginationPage, setPaginationPage] = React.useState(2);\n    const copy = {\n        \"pagination\": {\n            \"label\": \"Pagination\",\n            \"previous\": \"Previous\",\n            \"previousLabel\": \"Go to previous page\",\n            \"next\": \"Next\",\n            \"nextLabel\": \"Go to next page\"\n        }\n    };\n    return (<Pagination aria-label={copy.pagination.label}>\n          <PaginationContent>\n            <PaginationItem>\n              <PaginationPrevious aria-label={copy.pagination.previousLabel} aria-disabled={paginationPage === 1} href=\"#pagination-example\" onClick={event => { event.preventDefault(); setPaginationPage(value => Math.max(1, value - 1)); }}>{copy.pagination.previous}</PaginationPrevious>\n            </PaginationItem>\n            {[1, 2, 3].map(value => <PaginationItem key={value}>\n              <PaginationLink href=\"#pagination-example\" isActive={paginationPage === value} onClick={event => { event.preventDefault(); setPaginationPage(value); }}>{value}</PaginationLink>\n            </PaginationItem>)}\n            <PaginationItem>\n              <PaginationNext aria-label={copy.pagination.nextLabel} aria-disabled={paginationPage === 3} href=\"#pagination-example\" onClick={event => { event.preventDefault(); setPaginationPage(value => Math.min(3, value + 1)); }}>{copy.pagination.next}</PaginationNext>\n            </PaginationItem>\n          </PaginationContent>\n        </Pagination>);\n}",
  progress: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"progress\": {\n            \"registryBuild\": \"Registry build\",\n            \"themeTokens\": \"Theme tokens\",\n            \"waiting\": \"Waiting for data\"\n        }\n    };\n    return (<PreviewStack>\n          <div className=\"grid gap-3 border-b border-[var(--border)] py-3.5 [&>div]:flex [&>div]:items-center [&>div]:justify-between [&>div]:gap-4 [&>div]:text-sm\">\n            <div>\n              <span>{copy.progress.registryBuild}</span>\n              <strong>82%</strong>\n            </div>\n            <Progress aria-label={copy.progress.registryBuild} value={82}/>\n          </div>\n          <div className=\"grid gap-3 border-b border-[var(--border)] py-3.5 [&>div]:flex [&>div]:items-center [&>div]:justify-between [&>div]:gap-4 [&>div]:text-sm\">\n            <div>\n              <span>{copy.progress.themeTokens}</span>\n              <strong>12 / 16</strong>\n            </div>\n            <Progress aria-label={copy.progress.themeTokens} max={16} value={12}/>\n          </div>\n          <div className=\"grid gap-3 border-b border-[var(--border)] py-3.5 [&>div]:flex [&>div]:items-center [&>div]:justify-between [&>div]:gap-4 [&>div]:text-sm\">\n            <div>\n              <span>{copy.progress.waiting}</span>\n              <strong>—</strong>\n            </div>\n            <Progress aria-label={copy.progress.waiting} value={null}/>\n          </div>\n        </PreviewStack>);\n}",
  "radio-group": "export default function Example() {\n    const copy = {\n        \"radio\": {\n            \"label\": \"Interface density\",\n            \"compact\": \"Compact\",\n            \"compactBody\": \"Show more information on each screen.\",\n            \"comfortable\": \"Comfortable\",\n            \"comfortableBody\": \"Use the default spacing and gentle depth.\",\n            \"spacious\": \"Spacious\",\n            \"spaciousBody\": \"Provide generous spacing for touch interfaces.\"\n        }\n    };\n    return (<RadioGroup defaultValue=\"comfortable\" aria-label={copy.radio.label}>\n          <Label className=\"flex w-full max-w-[560px] cursor-pointer items-center gap-3 border-b border-[var(--border)] px-1 py-3.5 [&>span]:grid [&>span]:flex-1 [&>span]:gap-1 [&_small]:text-[var(--muted-foreground)]\" htmlFor=\"density-compact-doc\">\n            <RadioGroupItem id=\"density-compact-doc\" value=\"compact\"/>\n            <span>\n              <strong>{copy.radio.compact}</strong>\n              <small>{copy.radio.compactBody}</small>\n            </span>\n          </Label>\n          <Label className=\"flex w-full max-w-[560px] cursor-pointer items-center gap-3 border-b border-[var(--border)] px-1 py-3.5 [&>span]:grid [&>span]:flex-1 [&>span]:gap-1 [&_small]:text-[var(--muted-foreground)]\" htmlFor=\"density-comfortable-doc\">\n            <RadioGroupItem id=\"density-comfortable-doc\" value=\"comfortable\"/>\n            <span>\n              <strong>{copy.radio.comfortable}</strong>\n              <small>{copy.radio.comfortableBody}</small>\n            </span>\n          </Label>\n          <Label className=\"flex w-full max-w-[560px] cursor-pointer items-center gap-3 border-b border-[var(--border)] px-1 py-3.5 [&>span]:grid [&>span]:flex-1 [&>span]:gap-1 [&_small]:text-[var(--muted-foreground)]\" htmlFor=\"density-spacious-doc\">\n            <RadioGroupItem id=\"density-spacious-doc\" value=\"spacious\"/>\n            <span>\n              <strong>{copy.radio.spacious}</strong>\n              <small>{copy.radio.spaciousBody}</small>\n            </span>\n          </Label>\n        </RadioGroup>);\n}",
  "scroll-area": "export default function Example() {\n    const copy = {\n        \"scrollArea\": {\n            \"label\": \"Component status list\",\n            \"categories\": {\n                \"accessibility\": \"Accessibility\",\n                \"overlay\": \"Overlay\",\n                \"data\": \"Data\",\n                \"input\": \"Input\",\n                \"composite\": \"Composite\"\n            },\n            \"statuses\": {\n                \"ready\": \"Ready\",\n                \"review\": \"Review\",\n                \"planned\": \"Planned\"\n            }\n        }\n    };\n    return (<ScrollArea aria-label={copy.scrollArea.label} className=\"h-[280px] w-full max-w-[580px] p-2.5\">\n          {[\n            [\n                \"NVDA\",\n                copy.scrollArea.categories.accessibility,\n                copy.scrollArea.statuses.ready,\n                \"ready\",\n            ],\n            [\n                \"Dialog\",\n                copy.scrollArea.categories.overlay,\n                copy.scrollArea.statuses.ready,\n                \"ready\",\n            ],\n            [\n                \"Data table\",\n                copy.scrollArea.categories.data,\n                copy.scrollArea.statuses.review,\n                \"review\",\n            ],\n            [\n                \"Slider\",\n                copy.scrollArea.categories.input,\n                copy.scrollArea.statuses.ready,\n                \"ready\",\n            ],\n            [\n                \"Tooltip\",\n                copy.scrollArea.categories.overlay,\n                copy.scrollArea.statuses.ready,\n                \"ready\",\n            ],\n            [\n                \"Calendar\",\n                copy.scrollArea.categories.composite,\n                copy.scrollArea.statuses.planned,\n                \"planned\",\n            ],\n            [\n                \"Command\",\n                copy.scrollArea.categories.composite,\n                copy.scrollArea.statuses.planned,\n                \"planned\",\n            ],\n        ].map(([name, category, state, stateId]) => (<div className=\"flex items-center justify-between gap-4 border-b border-[var(--border)] p-3.5 last:border-0 [&>span]:grid [&>span]:gap-1 [&_small]:text-[var(--muted-foreground)]\" key={name}>\n              <span><strong>{name}</strong><small>{category}</small></span>\n              <Badge variant={stateId === \"ready\" ? \"primary\" : \"soft\"}>\n                {state}\n              </Badge>\n            </div>))}\n        </ScrollArea>);\n}",
  select: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nfunction PreviewField({ children, htmlFor, label }: {\n    children: React.ReactNode;\n    htmlFor?: string;\n    label: string;\n}) {\n    return <div className=\"grid gap-2\">{htmlFor ? <Label htmlFor={htmlFor}>{label}</Label> : <span className=\"text-sm font-medium\">{label}</span>}{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"select\": {\n            \"region\": \"Region\",\n            \"asiaPacific\": \"Asia Pacific\",\n            \"seoul\": \"Seoul, Korea\",\n            \"tokyo\": \"Tokyo, Japan\",\n            \"singapore\": \"Singapore\",\n            \"northAmerica\": \"North America\",\n            \"sanFrancisco\": \"San Francisco, USA\",\n            \"disabled\": \"Disabled\",\n            \"selectedByAdmin\": \"Selected by an administrator\"\n        }\n    };\n    return (<PreviewStack>\n          <PreviewField htmlFor=\"docs-select-region\" label={copy.select.region}>\n            <Select defaultValue=\"kr\" id=\"docs-select-region\">\n              <SelectGroup label={copy.select.asiaPacific}>\n                <SelectItem value=\"kr\">{copy.select.seoul}</SelectItem>\n                <SelectItem value=\"jp\">{copy.select.tokyo}</SelectItem>\n                <SelectItem value=\"sg\">{copy.select.singapore}</SelectItem>\n              </SelectGroup>\n              <SelectGroup label={copy.select.northAmerica}>\n                <SelectItem value=\"us-west\">\n                  {copy.select.sanFrancisco}\n                </SelectItem>\n              </SelectGroup>\n            </Select>\n          </PreviewField>\n          <PreviewField htmlFor=\"docs-select-disabled\" label={copy.select.disabled}>\n            <Select disabled defaultValue=\"locked\" id=\"docs-select-disabled\">\n              <SelectItem value=\"locked\">\n                {copy.select.selectedByAdmin}\n              </SelectItem>\n            </Select>\n          </PreviewField>\n        </PreviewStack>);\n}",
  separator: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"separator\": {\n            \"title\": \"Component documentation\",\n            \"description\": \"Examples, installation steps and component properties.\",\n            \"preview\": \"Preview\",\n            \"installation\": \"Installation\"\n        }\n    };\n    return (<PreviewStack>\n          <div className=\"grid gap-1 [&_span]:text-sm [&_span]:text-[var(--muted-foreground)]\">\n            <strong>{copy.separator.title}</strong>\n            <span>{copy.separator.description}</span>\n          </div>\n          <Separator />\n          <div className=\"flex items-center gap-3 h-5 text-sm\">\n            <a href=\"#preview\">{copy.separator.preview}</a>\n            <Separator decorative={false} orientation=\"vertical\"/>\n            <a href=\"#installation\">{copy.separator.installation}</a>\n            <Separator decorative={false} orientation=\"vertical\"/>\n            <a href=\"#api-reference\">API</a>\n          </div>\n        </PreviewStack>);\n}",
  skeleton: "export default function Example() {\n    const copy = {\n        \"skeleton\": {\n            \"loading\": \"Loading content\"\n        }\n    };\n    return (<div className=\"w-full max-w-[520px] overflow-hidden rounded-[var(--neu-radius-surface)] border border-[var(--border)]\" aria-label={copy.skeleton.loading}>\n          <Skeleton className=\"h-[150px] w-full rounded-none\"/>\n          <div className=\"grid gap-4 p-5\">\n            <div className=\"flex items-center gap-3\">\n              <Skeleton className=\"size-12 rounded-full\"/>\n              <div className=\"grid flex-1 gap-2.5\">\n                <Skeleton className=\"h-3.5 w-[58%]\"/>\n                <Skeleton className=\"h-2.5 w-full\"/>\n              </div>\n            </div>\n            <Skeleton className=\"h-2.5 w-full\"/>\n            <Skeleton className=\"h-2.5 w-full max-w-[72%]\"/>\n          </div>\n        </div>);\n}",
  slider: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nexport default function Example() {\n    const [sliderValue, setSliderValue] = React.useState([32, 72]);\n    const copy = {\n        \"slider\": {\n            \"priceRange\": \"Price range\",\n            \"minimumPrice\": \"Minimum price\",\n            \"maximumPrice\": \"Maximum price\",\n            \"verticalVolume\": \"Vertical volume\",\n            \"verticalOrientation\": \"Vertical orientation\"\n        }\n    };\n    return (<PreviewStack>\n          <div className=\"grid gap-3 border-b border-[var(--border)] py-3.5 [&>div]:flex [&>div]:items-center [&>div]:justify-between [&>div]:gap-4 [&>div]:text-sm\">\n            <div>\n              <span>{copy.slider.priceRange}</span>\n              <strong>₩{sliderValue[0]}K – ₩{sliderValue[1]}K</strong>\n            </div>\n            <Slider aria-label={copy.slider.priceRange} max={100} min={0} step={1} thumbLabels={[\n            copy.slider.minimumPrice,\n            copy.slider.maximumPrice,\n        ]} value={sliderValue} onValueChange={(nextValue) => {\n            setSliderValue(Array.isArray(nextValue) ? [...nextValue] : [nextValue]);\n        }}/>\n          </div>\n          <div className=\"flex items-center gap-3 min-h-[200px] justify-center text-sm\">\n            <Slider aria-label={copy.slider.verticalVolume} defaultValue={[60]} orientation=\"vertical\" thumbLabels={[copy.slider.verticalVolume]}/>\n            <span>{copy.slider.verticalOrientation}</span>\n          </div>\n        </PreviewStack>);\n}",
  switch: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nexport default function Example() {\n    const [switchValue, setSwitchValue] = React.useState(true);\n    const copy = {\n        \"switch\": {\n            \"livePrices\": \"Live prices\",\n            \"livePricesBody\": \"Refresh market prices automatically.\",\n            \"emailAlerts\": \"Email alerts\",\n            \"emailAlertsBody\": \"Receive only important changes.\",\n            \"adminPolicy\": \"Administrator policy\",\n            \"adminPolicyBody\": \"This setting is locked for the current workspace.\"\n        }\n    };\n    return (<PreviewStack compact>\n          <Label className=\"flex w-full max-w-[560px] cursor-pointer items-center gap-3 border-b border-[var(--border)] px-1 py-3.5 [&>span]:grid [&>span]:flex-1 [&>span]:gap-1 [&_small]:text-[var(--muted-foreground)]\" htmlFor=\"docs-switch-live\">\n            <span>\n              <strong>{copy.switch.livePrices}</strong>\n              <small>{copy.switch.livePricesBody}</small>\n            </span>\n            <Switch id=\"docs-switch-live\" checked={switchValue} onCheckedChange={setSwitchValue}/>\n          </Label>\n          <Label className=\"flex w-full max-w-[560px] cursor-pointer items-center gap-3 border-b border-[var(--border)] px-1 py-3.5 [&>span]:grid [&>span]:flex-1 [&>span]:gap-1 [&_small]:text-[var(--muted-foreground)]\" htmlFor=\"docs-switch-email\">\n            <span>\n              <strong>{copy.switch.emailAlerts}</strong>\n              <small>{copy.switch.emailAlertsBody}</small>\n            </span>\n            <Switch id=\"docs-switch-email\"/>\n          </Label>\n          <Label className=\"flex w-full max-w-[560px] cursor-pointer items-center gap-3 border-b border-[var(--border)] px-1 py-3.5 [&>span]:grid [&>span]:flex-1 [&>span]:gap-1 [&_small]:text-[var(--muted-foreground)]\" htmlFor=\"docs-switch-locked\">\n            <span>\n              <strong>{copy.switch.adminPolicy}</strong>\n              <small>{copy.switch.adminPolicyBody}</small>\n            </span>\n            <Switch id=\"docs-switch-locked\" disabled/>\n          </Label>\n        </PreviewStack>);\n}",
  table: "export default function Example() {\n    const copy = {\n        \"table\": {\n            \"caption\": \"Watchlist · Data delayed by 10 minutes\",\n            \"symbol\": \"Symbol\",\n            \"price\": \"Price\",\n            \"change\": \"Change\",\n            \"status\": \"Status\",\n            \"open\": \"Open\",\n            \"selected\": \"Selected\",\n            \"watch\": \"Watch\"\n        }\n    };\n    return (<Table>\n          <TableCaption>{copy.table.caption}</TableCaption>\n          <TableHeader>\n            <TableRow>\n              <TableHead>{copy.table.symbol}</TableHead>\n              <TableHead>{copy.table.price}</TableHead>\n              <TableHead>{copy.table.change}</TableHead>\n              <TableHead>{copy.table.status}</TableHead>\n            </TableRow>\n          </TableHeader>\n          <TableBody>\n            <TableRow>\n              <TableCell><strong>NVDA</strong></TableCell>\n              <TableCell>$181.92</TableCell>\n              <TableCell className=\"font-semibold text-[var(--success)]\">+2.41%</TableCell>\n              <TableCell>\n                <Badge variant=\"primary\">{copy.table.open}</Badge>\n              </TableCell>\n            </TableRow>\n            <TableRow data-state=\"selected\">\n              <TableCell><strong>005930</strong></TableCell>\n              <TableCell>₩72,400</TableCell>\n              <TableCell className=\"font-semibold text-[var(--success)]\">+1.08%</TableCell>\n              <TableCell>\n                <Badge variant=\"soft\">{copy.table.selected}</Badge>\n              </TableCell>\n            </TableRow>\n            <TableRow>\n              <TableCell><strong>TSLA</strong></TableCell>\n              <TableCell>$318.27</TableCell>\n              <TableCell className=\"font-semibold text-[var(--destructive)]\">−0.64%</TableCell>\n              <TableCell>\n                <Badge variant=\"outline\">{copy.table.watch}</Badge>\n              </TableCell>\n            </TableRow>\n          </TableBody>\n        </Table>);\n}",
  tabs: "export default function Example() {\n    const copy = {\n        \"tabs\": {\n            \"label\": \"Portfolio views\",\n            \"overview\": \"Overview\",\n            \"activity\": \"Activity\",\n            \"settings\": \"Settings\",\n            \"portfolioValue\": \"Portfolio value\",\n            \"monthlyChange\": \"+6.8% this month\",\n            \"activityBody\": \"There were 12 trades and 4 price alerts in the last 7 days.\",\n            \"settingsBody\": \"Configure account sync and alert settings in this panel.\"\n        }\n    };\n    return (<Tabs defaultValue=\"overview\">\n          <TabsList aria-label={copy.tabs.label}>\n            <TabsTrigger value=\"overview\">{copy.tabs.overview}</TabsTrigger>\n            <TabsTrigger value=\"activity\">{copy.tabs.activity}</TabsTrigger>\n            <TabsTrigger value=\"settings\">{copy.tabs.settings}</TabsTrigger>\n          </TabsList>\n          <TabsContent value=\"overview\" className=\"grid min-h-[140px] content-center gap-2 py-6 text-sm [&_strong]:text-3xl [&_small]:text-[var(--success)]\">\n            <span className=\"text-sm font-medium text-[var(--muted-foreground)]\">\n              {copy.tabs.portfolioValue}\n            </span>\n            <strong>₩18,420,000</strong>\n            <small>{copy.tabs.monthlyChange}</small>\n          </TabsContent>\n          <TabsContent value=\"activity\" className=\"grid min-h-[140px] content-center gap-2 py-6 text-sm [&_strong]:text-3xl [&_small]:text-[var(--success)]\">\n            {copy.tabs.activityBody}\n          </TabsContent>\n          <TabsContent value=\"settings\" className=\"grid min-h-[140px] content-center gap-2 py-6 text-sm [&_strong]:text-3xl [&_small]:text-[var(--success)]\">\n            {copy.tabs.settingsBody}\n          </TabsContent>\n        </Tabs>);\n}",
  textarea: "function PreviewStack({ children, compact = false }: {\n    children: React.ReactNode;\n    compact?: boolean;\n}) {\n    return <div className={compact ? \"mx-auto grid w-full max-w-[540px] gap-5\" : \"grid w-full gap-5\"}>{children}</div>;\n}\nfunction PreviewField({ children, htmlFor, label }: {\n    children: React.ReactNode;\n    htmlFor?: string;\n    label: string;\n}) {\n    return <div className=\"grid gap-2\">{htmlFor ? <Label htmlFor={htmlFor}>{label}</Label> : <span className=\"text-sm font-medium\">{label}</span>}{children}</div>;\n}\nexport default function Example() {\n    const copy = {\n        \"textarea\": {\n            \"investmentNote\": \"Investment note\",\n            \"investmentNoteValue\": \"Review trading volume and support levels after the earnings report.\",\n            \"validationState\": \"Validation state\",\n            \"invalidValue\": \"This note is too short\",\n            \"disabled\": \"Disabled\",\n            \"disabledValue\": \"Shared notes cannot be edited.\"\n        }\n    };\n    return (<PreviewStack>\n          <PreviewField htmlFor=\"docs-textarea-note\" label={copy.textarea.investmentNote}>\n            <Textarea defaultValue={copy.textarea.investmentNoteValue} id=\"docs-textarea-note\" maxLength={240}/>\n          </PreviewField>\n          <PreviewField htmlFor=\"docs-textarea-invalid\" label={copy.textarea.validationState}>\n            <Textarea aria-invalid defaultValue={copy.textarea.invalidValue} id=\"docs-textarea-invalid\"/>\n          </PreviewField>\n          <PreviewField htmlFor=\"docs-textarea-disabled\" label={copy.textarea.disabled}>\n            <Textarea defaultValue={copy.textarea.disabledValue} disabled id=\"docs-textarea-disabled\"/>\n          </PreviewField>\n        </PreviewStack>);\n}",
  tooltip: "export default function Example() {\n    const copy = {\n        \"tooltip\": {\n            \"addToWatchlist\": \"Add to watchlist\",\n            \"keyboardFocus\": \"Keyboard focus\",\n            \"keyboardFocusBody\": \"The same description appears when you reach it with Tab.\",\n            \"hint\": \"Hover the button or move focus to it.\"\n        }\n    };\n    return (<TooltipProvider delay={100}>\n          <div className=\"flex items-center gap-3\">\n            <Tooltip>\n              <TooltipTrigger render={<Button size=\"icon\" variant=\"soft\" aria-label={copy.tooltip.addToWatchlist}/>}>\n                <svg aria-hidden=\"true\" className=\"size-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\">\n                  <path d=\"M12 5v14M5 12h14\"/>\n                </svg>\n              </TooltipTrigger>\n              <TooltipContent side=\"top\">\n                {copy.tooltip.addToWatchlist}\n              </TooltipContent>\n            </Tooltip>\n            <Tooltip>\n              <TooltipTrigger render={<Button variant=\"ghost\"/>}>\n                {copy.tooltip.keyboardFocus}\n              </TooltipTrigger>\n              <TooltipContent side=\"bottom\">\n                {copy.tooltip.keyboardFocusBody}\n              </TooltipContent>\n            </Tooltip>\n            <span className=\"text-xs text-[var(--muted-foreground)]\">{copy.tooltip.hint}</span>\n          </div>\n        </TooltipProvider>);\n}",
"alert-dialog": "export default function Example() {\n  const [message, setMessage] = React.useState(\"\");\n  return (<div className=\"grid gap-3\"><AlertDialog><AlertDialogTrigger render={<Button variant=\"destructive\" />}>{\"Delete draft\"}</AlertDialogTrigger><AlertDialogContent><AlertDialogTitle>{\"Delete this draft?\"}</AlertDialogTitle><AlertDialogDescription>{\"This cannot be undone. Confirm explicitly to continue.\"}</AlertDialogDescription><AlertDialogFooter><AlertDialogCancel>{\"Go back\"}</AlertDialogCancel><AlertDialogAction onClick={() => setMessage(\"Draft deleted.\")}>{\"Delete draft\"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog><p role=\"status\" className=\"text-sm text-[var(--muted-foreground)]\">{message}</p></div>);\n}",
"popover": "export default function Example() {\n\n  return (<Popover><PopoverTrigger render={<Button />}>{\"Notification settings\"}</PopoverTrigger><PopoverContent><PopoverTitle>{\"Tune your notifications\"}</PopoverTitle><PopoverDescription>{\"Keep your focus with only the updates that matter.\"}</PopoverDescription><PopoverClose render={<Button variant=\"primary\" />}>{\"Close\"}</PopoverClose></PopoverContent></Popover>);\n}",
"hover-card": "export default function Example() {\n  const id = React.useId();\n  return (<HoverCard><HoverCardTrigger href=\"#profile-preview\" className=\"inline-flex items-center gap-3 rounded-[var(--neu-radius-control)] border border-[color:var(--neu-edge)] bg-[var(--neu-surface)] px-4 py-3 font-semibold text-[var(--foreground)] [box-shadow:var(--neu-shadow-raised-sm)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]\">{\"Preview profile\"} <svg aria-hidden=\"true\" className=\"size-4 shrink-0\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"M7 17 17 7M7 7h10v10\" /></svg></HoverCardTrigger><HoverCardContent><strong id=\"profile-preview\">Alex Kim</strong><p>{\"Product designer · Seoul\"}</p></HoverCardContent></HoverCard>);\n}",
"sheet": "export default function Example() {\n  const [name, setName] = React.useState(\"Alex\");\n  const nameField = <Field name=\"displayName\"><FieldLabel>{\"Display name\"}</FieldLabel><FieldControl required value={name} onValueChange={setName} /><FieldDescription>{\"Enter the name shown on your profile.\"}</FieldDescription><FieldError match=\"valueMissing\">{\"Enter a name.\"}</FieldError></Field>;\n  return (<Sheet><SheetTrigger render={<Button />}>{\"Profile settings\"}</SheetTrigger><SheetContent closeLabel={\"Close\"}><SheetTitle>{\"Profile settings\"}</SheetTitle><SheetDescription>{\"Enter the name shown on your profile.\"}</SheetDescription>{nameField}<SheetClose render={<Button variant=\"primary\" />}>{\"Close\"}</SheetClose></SheetContent></Sheet>);\n}",
"collapsible": "export default function Example() {\n  const [expanded, setExpanded] = React.useState(false);\n  return (<Collapsible open={expanded} onOpenChange={setExpanded}><CollapsibleTrigger>{\"Advanced settings\"}</CollapsibleTrigger><CollapsibleContent><div>{\"Reveal optional settings without changing the defaults.\"}</div></CollapsibleContent></Collapsible>);\n}",
"toggle": "export default function Example() {\n\n  return (<div className=\"flex flex-wrap gap-3\"><Toggle aria-label={\"Pin\"}><svg aria-hidden=\"true\" className=\"size-4 shrink-0\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"M16 3l5 5-4 1-4 4-1 4-5-5 4-1 4-4Z\" /><path d=\"m7 17-4 4\" /></svg>{\"Pin\"}</Toggle><Toggle defaultPressed>{\"Pin\"}</Toggle><Toggle disabled>{\"Locked\"}</Toggle></div>);\n}",
"toggle-group": "export default function Example() {\n  const text = {\"open\":\"Notification settings\",\"title\":\"Tune your notifications\",\"body\":\"Keep your focus with only the updates that matter.\",\"close\":\"Close\",\"discard\":\"Delete draft\",\"confirm\":\"Delete this draft?\",\"warning\":\"This cannot be undone. Confirm explicitly to continue.\",\"cancel\":\"Go back\",\"done\":\"Draft deleted.\",\"profile\":\"Preview profile\",\"person\":\"Product designer · Seoul\",\"details\":\"Advanced settings\",\"detailBody\":\"Reveal optional settings without changing the defaults.\",\"pin\":\"Pin\",\"locked\":\"Locked\",\"align\":\"Alignment\",\"left\":\"Left\",\"center\":\"Center\",\"right\":\"Right\",\"tools\":\"Document tools\",\"undo\":\"Undo\",\"redo\":\"Redo\",\"save\":\"Save changes\",\"saved\":\"Local example saved.\",\"name\":\"Display name\",\"hint\":\"Enter the name shown on your profile.\",\"required\":\"Enter a name.\",\"settings\":\"Profile settings\",\"quantity\":\"Seats\",\"increase\":\"Increase seats\",\"decrease\":\"Decrease seats\",\"storage\":\"Storage used\",\"city\":\"Search cities\",\"empty\":\"No matching cities.\",\"reset\":\"Reset\",\"editing\":\"Unsaved changes\",\"quiet\":\"Saved state\"};\n  const [alignment, setAlignment] = React.useState<string[]>([\"left\"]);\n  return (<div className=\"grid gap-3\"><ToggleGroup aria-label={\"Alignment\"} value={alignment} onValueChange={setAlignment}><ToggleGroupItem value=\"left\">{\"Left\"}</ToggleGroupItem><ToggleGroupItem value=\"center\">{\"Center\"}</ToggleGroupItem><ToggleGroupItem value=\"right\">{\"Right\"}</ToggleGroupItem></ToggleGroup><output className=\"text-sm text-[var(--muted-foreground)]\">{alignment.map(value => text[value as \"left\" | \"center\" | \"right\"]).join(\", \")}</output></div>);\n}",
"toolbar": "export default function Example() {\n  const [message, setMessage] = React.useState(\"\");\n  return (<div className=\"grid gap-3\"><Toolbar aria-label={\"Document tools\"}><ToolbarGroup><ToolbarButton onClick={() => setMessage(\"Undo\")}>{\"Undo\"}</ToolbarButton><ToolbarButton disabled>{\"Redo\"}</ToolbarButton></ToolbarGroup><ToolbarSeparator /><ToolbarButton onClick={() => setMessage(\"Local example saved.\")}>{\"Save changes\"}</ToolbarButton></Toolbar><p role=\"status\" className=\"text-sm text-[var(--muted-foreground)]\">{message}</p></div>);\n}",
"field": "export default function Example() {\n  const [name, setName] = React.useState(\"Alex\");\n  const nameField = <Field name=\"displayName\"><FieldLabel>{\"Display name\"}</FieldLabel><FieldControl required value={name} onValueChange={setName} /><FieldDescription>{\"Enter the name shown on your profile.\"}</FieldDescription><FieldError match=\"valueMissing\">{\"Enter a name.\"}</FieldError></Field>;\n  return (<div className=\"grid w-full max-w-sm gap-5\">{nameField}<Field invalid><FieldLabel>{\"Display name\"}</FieldLabel><FieldControl defaultValue=\"\" /><FieldError match>{\"Enter a name.\"}</FieldError></Field></div>);\n}",
"fieldset": "export default function Example() {\n  const [name, setName] = React.useState(\"Alex\");\n  const nameField = <Field name=\"displayName\"><FieldLabel>{\"Display name\"}</FieldLabel><FieldControl required value={name} onValueChange={setName} /><FieldDescription>{\"Enter the name shown on your profile.\"}</FieldDescription><FieldError match=\"valueMissing\">{\"Enter a name.\"}</FieldError></Field>;\n  return (<Fieldset className=\"w-full max-w-sm\"><FieldsetLegend>{\"Profile settings\"}</FieldsetLegend>{nameField}</Fieldset>);\n}",
"form": "export default function Example() {\n  const [message, setMessage] = React.useState(\"\");\n  const [name, setName] = React.useState(\"Alex\");\n  const [savedName, setSavedName] = React.useState(\"Alex\");\n  const nameField = <Field name=\"displayName\"><FieldLabel>{\"Display name\"}</FieldLabel><FieldControl required value={name} onValueChange={setName} /><FieldDescription>{\"Enter the name shown on your profile.\"}</FieldDescription><FieldError match=\"valueMissing\">{\"Enter a name.\"}</FieldError></Field>;\n  return (<Form className=\"w-full max-w-sm\" onFormSubmit={() => { setSavedName(name); setMessage(\"Local example saved.\"); }} onReset={() => { setName(savedName); setMessage(\"\"); }}>\n      {nameField}<div className=\"flex flex-wrap gap-3\"><Button type=\"submit\" variant=\"primary\">{\"Save changes\"}</Button><Button type=\"reset\">{\"Reset\"}</Button></div><p role=\"status\" className=\"text-sm text-[var(--muted-foreground)]\">{name !== savedName ? \"Unsaved changes\" : message || \"Saved state\"}</p>\n    </Form>);\n}",
"number-field": "export default function Example() {\n  const id = React.useId();\n  return (<NumberField id={id} defaultValue={3} min={1} max={8}><label htmlFor={id} className=\"text-sm font-semibold\">{\"Seats\"}</label><NumberFieldGroup><NumberFieldDecrement aria-label={\"Decrease seats\"} /><NumberFieldInput /><NumberFieldIncrement aria-label={\"Increase seats\"} /></NumberFieldGroup></NumberField>);\n}",
"meter": "export default function Example() {\n\n  return (<Meter value={64} className=\"w-full max-w-sm\"><div className=\"flex justify-between gap-4\"><MeterLabel>{\"Storage used\"}</MeterLabel><MeterValue /></div><MeterTrack><MeterIndicator /></MeterTrack><p className=\"text-xs text-[var(--muted-foreground)]\">64 GB / 100 GB</p></Meter>);\n}",
"combobox": "export default function Example() {\n  const cities = [\"Busan\", \"London\", \"Seoul\", \"Tokyo\"];\n  return (<div className=\"w-full max-w-sm\"><Combobox items={cities}><ComboboxLabel>{\"Search cities\"}</ComboboxLabel><ComboboxInput placeholder={\"Search cities\"} /><ComboboxContent><ComboboxEmpty>{\"No matching cities.\"}</ComboboxEmpty><ComboboxList>{(city: string) => <ComboboxItem key={city} value={city}>{city}</ComboboxItem>}</ComboboxList></ComboboxContent></Combobox></div>);\n}","calendar": "const locales = { en: enUS, ko, ja, zh: zhCN };\nconst copy = {\n  en: { single: \"Single date\", range: \"Date range\", clear: \"Clear range\", empty: \"No date selected\" },\n  ko: { single: \"날짜 선택\", range: \"기간 선택\", clear: \"기간 초기화\", empty: \"선택한 날짜 없음\" },\n  ja: { single: \"日付選択\", range: \"期間選択\", clear: \"期間をクリア\", empty: \"日付未選択\" },\n  zh: { single: \"选择日期\", range: \"选择范围\", clear: \"清除范围\", empty: \"未选择日期\" },\n};\nfunction stamp(date: Date) {\n  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, \"0\")}-${String(date.getDate()).padStart(2, \"0\")}`;\n}\n\nexport default function CalendarExample({ locale = \"en\" }: { locale?: keyof typeof copy }) {\n  const text = copy[locale];\n  const [date, setDate] = React.useState<Date | undefined>(new Date(2026, 8, 15));\n  const [range, setRange] = React.useState<DateRange | undefined>({ from: new Date(2026, 8, 12), to: new Date(2026, 8, 17) });\n  return <div className=\"flex max-w-full flex-wrap items-start gap-6\">\n    <section data-calendar=\"single\" aria-label={text.single} className=\"grid max-w-full gap-3\"><h3 className=\"text-sm font-semibold\">{text.single}</h3><Calendar mode=\"single\" selected={date} onSelect={setDate} defaultMonth={new Date(2026, 8)} today={new Date(2026, 8, 15)} disabled={new Date(2026, 8, 20)} locale={locales[locale]} /><output aria-live=\"polite\" data-testid=\"calendar-value\" className=\"text-sm text-[var(--muted-foreground)]\">{date ? stamp(date) : text.empty}</output></section>\n    <section data-calendar=\"range\" aria-label={text.range} className=\"grid max-w-full gap-3\"><h3 className=\"text-sm font-semibold\">{text.range}</h3><Calendar mode=\"range\" selected={range} onSelect={setRange} defaultMonth={new Date(2026, 8)} today={new Date(2026, 8, 15)} locale={locales[locale]} /><output aria-live=\"polite\" data-testid=\"calendar-range\" className=\"text-sm text-[var(--muted-foreground)]\">{range?.from ? `${stamp(range.from)} / ${range.to ? stamp(range.to) : \"…\"}` : text.empty}</output><Button size=\"sm\" variant=\"ghost\" className=\"w-fit justify-self-start\" onClick={() => setRange(undefined)}>{text.clear}</Button></section>\n  </div>;\n}",
"date-picker": "const locales = { en: enUS, ko, ja, zh: zhCN };\nconst copy = {\n  en: { label: \"Due date\", choose: \"Select date\", clear: \"Clear date\", locked: \"Locked date\", reset: \"Reset date\", hint: \"Dates are stored as local calendar dates, not UTC timestamps.\" },\n  ko: { label: \"마감일\", choose: \"날짜 선택\", clear: \"날짜 지우기\", locked: \"변경 불가 날짜\", reset: \"날짜 초기화\", hint: \"날짜는 UTC 시각이 아닌 현지 달력의 날짜로 저장됩니다.\" },\n  ja: { label: \"期限\", choose: \"日付を選択\", clear: \"日付をクリア\", locked: \"変更不可の日付\", reset: \"日付をリセット\", hint: \"UTC時刻ではなく、現地のカレンダー日付として保存します。\" },\n  zh: { label: \"截止日期\", choose: \"选择日期\", clear: \"清除日期\", locked: \"锁定日期\", reset: \"重置日期\", hint: \"日期按本地日历保存，而非 UTC 时间戳。\" },\n};\n\nexport default function DatePickerExample({ locale = \"en\" }: { locale?: keyof typeof copy }) {\n  const text = copy[locale];\n  const id = React.useId();\n  const [date, setDate] = React.useState<Date | undefined>(new Date(2026, 8, 15));\n  return <form className=\"grid w-full max-w-sm gap-4\" onSubmit={event => event.preventDefault()} onReset={() => setDate(new Date(2026, 8, 15))}>\n    <label htmlFor={id} className=\"text-sm font-semibold\">{text.label}</label>\n    <DatePicker id={id} name=\"dueDate\" label={text.label} value={date} onValueChange={setDate} locale={locales[locale]} placeholder={text.choose} clearLabel={text.clear} describedBy={`${id}-hint`} disabledDates={{ before: new Date(2026, 8, 10) }} startMonth={new Date(2026, 8)} endMonth={new Date(2027, 11)} />\n    <p id={`${id}-hint`} className=\"text-sm leading-relaxed text-[var(--muted-foreground)]\">{text.hint}</p>\n    <Button type=\"reset\" size=\"sm\" className=\"w-fit\">{text.reset}</Button>\n    <DatePicker label={text.locked} value={new Date(2026, 8, 15)} onValueChange={() => {}} disabled locale={locales[locale]} clearLabel={text.clear} />\n  </form>;\n}",
"data-table": "type Project = { id: string; name: string; status: \"active\" | \"paused\"; seats: number };\nconst features = tableFeatures({\n  columnFilteringFeature, columnVisibilityFeature, globalFilteringFeature,\n  rowPaginationFeature, rowSelectionFeature, rowSortingFeature,\n  filteredRowModel: createFilteredRowModel(), sortedRowModel: createSortedRowModel(), paginatedRowModel: createPaginatedRowModel(),\n  filterFns: { includesString: filterFn_includesString, equalsString: filterFn_equalsString },\n  sortFns: { alphanumeric: sortFn_alphanumeric, text: sortFn_text },\n});\nconst data: Project[] = [\n  { id: \"p1\", name: \"Atlas\", status: \"active\", seats: 12 },\n  { id: \"p2\", name: \"Beacon\", status: \"paused\", seats: 4 },\n  { id: \"p3\", name: \"Cedar\", status: \"active\", seats: 8 },\n  { id: \"p4\", name: \"Delta\", status: \"active\", seats: 20 },\n  { id: \"p5\", name: \"Echo\", status: \"paused\", seats: 6 },\n  { id: \"p6\", name: \"Foxtrot\", status: \"active\", seats: 16 },\n  { id: \"p7\", name: \"Grove\", status: \"active\", seats: 3 },\n  { id: \"p8\", name: \"Harbor\", status: \"paused\", seats: 10 },\n];\nconst copy = {\n  en: { name: \"Project\", status: \"Status\", seats: \"Seats\", search: \"Search projects\", all: \"All statuses\", active: \"Active\", paused: \"Paused\", selectPage: \"Select current page\", select: \"Select\", selected: \"Selected across all pages\", clear: \"Clear selection\", empty: \"No matching projects.\", caption: \"Workspace projects — illustrative data\", previous: \"Previous\", next: \"Next\", rows: \"Rows per page\", page: \"Page\" },\n  ko: { name: \"프로젝트\", status: \"상태\", seats: \"좌석\", search: \"프로젝트 검색\", all: \"전체 상태\", active: \"활성\", paused: \"일시 중지\", selectPage: \"현재 페이지 전체 선택\", select: \"선택\", selected: \"전체 페이지에서 선택됨\", clear: \"선택 해제\", empty: \"일치하는 프로젝트가 없습니다.\", caption: \"워크스페이스 프로젝트 — 예시 데이터\", previous: \"이전\", next: \"다음\", rows: \"페이지당 행\", page: \"페이지\" },\n  ja: { name: \"プロジェクト\", status: \"状態\", seats: \"座席\", search: \"プロジェクトを検索\", all: \"すべての状態\", active: \"有効\", paused: \"一時停止\", selectPage: \"現在のページを選択\", select: \"選択\", selected: \"全ページの選択数\", clear: \"選択解除\", empty: \"一致するプロジェクトはありません。\", caption: \"ワークスペース — サンプルデータ\", previous: \"前へ\", next: \"次へ\", rows: \"ページあたりの行\", page: \"ページ\" },\n  zh: { name: \"项目\", status: \"状态\", seats: \"座位\", search: \"搜索项目\", all: \"全部状态\", active: \"活跃\", paused: \"暂停\", selectPage: \"选择当前页\", select: \"选择\", selected: \"所有页面已选\", clear: \"清除选择\", empty: \"没有匹配的项目。\", caption: \"工作区项目 — 示例数据\", previous: \"上一页\", next: \"下一页\", rows: \"每页行数\", page: \"页\" },\n};\n\nexport default function DataTableExample({ locale = \"en\" }: { locale?: keyof typeof copy }) {\n  const text = copy[locale];\n  const columns = React.useMemo<ColumnDef<typeof features, Project>[]>(() => [\n    { id: \"selection\", enableSorting: false, enableGlobalFilter: false,\n      header: ({ table }) => <Checkbox aria-label={text.selectPage} checked={table.getIsAllPageRowsSelected() ? true : table.getIsSomePageRowsSelected() ? \"indeterminate\" : false} onCheckedChange={checked => table.toggleAllPageRowsSelected(checked === true)} />,\n      cell: ({ row }) => <Checkbox aria-label={`${text.select} ${row.original.name}`} checked={row.getIsSelected()} onCheckedChange={checked => row.toggleSelected(checked === true)} /> },\n    { accessorKey: \"name\", header: ({ column }) => <DataTableColumnHeader column={column} title={text.name} /> },\n    { accessorKey: \"status\", header: text.status, enableSorting: false, filterFn: \"equalsString\", cell: ({ row }) => <span className=\"inline-flex items-center gap-2 whitespace-nowrap rounded-full border border-[var(--border)] px-2.5 py-1 text-xs font-medium\"><span aria-hidden=\"true\">{row.original.status === \"active\" ? \"●\" : \"Ⅱ\"}</span>{text[row.original.status]}</span> },\n    { accessorKey: \"seats\", header: ({ column }) => <DataTableColumnHeader column={column} title={text.seats} />, cell: ({ row }) => <span className=\"tabular-nums\">{row.original.seats}</span> },\n  ], [text]);\n  const table = useTable({ features, data, columns, getRowId: row => row.id, globalFilterFn: \"includesString\", initialState: { pagination: { pageIndex: 0, pageSize: 5 } } });\n  return <div className=\"grid w-full min-w-0 gap-4\">\n    <DataTable table={table} caption={text.caption} emptyMessage={text.empty}>\n      <div className=\"flex flex-wrap items-center gap-3\"><Input aria-label={text.search} placeholder={text.search} className=\"min-w-0 flex-1 basis-44\" value={(table.state.globalFilter as string) ?? \"\"} onChange={event => { table.setGlobalFilter(event.target.value); table.setPageIndex(0); }} /><div className=\"w-40 max-w-full\"><Select aria-label={text.status} value={(table.getColumn(\"status\")?.getFilterValue() as string) ?? \"\"} onChange={event => { table.getColumn(\"status\")?.setFilterValue(event.target.value || undefined); table.setPageIndex(0); }}><SelectItem value=\"\">{text.all}</SelectItem><SelectItem value=\"active\">{text.active}</SelectItem><SelectItem value=\"paused\">{text.paused}</SelectItem></Select></div></div>\n    </DataTable>\n    <div className=\"flex flex-wrap items-center justify-between gap-2\"><output data-testid=\"selected-rows\" className=\"text-sm text-[var(--muted-foreground)]\">{text.selected}: {table.getSelectedRowModel().rows.length}</output><Button variant=\"ghost\" size=\"sm\" disabled={!table.getSelectedRowModel().rows.length} onClick={() => table.resetRowSelection()}>{text.clear}</Button></div>\n    <DataTablePagination table={table} labels={{ previous: text.previous, next: text.next, rowsPerPage: text.rows, page: (current, total) => `${text.page} ${current} / ${total}` }} />\n  </div>;\n}",
"toast": "const copy = {\n  en: { save: \"Show success\", success: \"Changes saved\", body: \"This is a local demonstration. No server request was made.\", fail: \"Show error\", error: \"Could not save\", retry: \"Your changes are retained. Try again.\", archive: \"Archive draft\", archived: \"Draft archived\", undo: \"Undo\", undone: \"Archive undone\", idle: \"Draft available\", timed: \"Show timed toast\", quick: \"Quick update\", region: \"Notifications\", close: \"Dismiss notification\" },\n  ko: { save: \"성공 알림\", success: \"변경 사항 저장됨\", body: \"로컬 예제이며 서버 요청은 전송하지 않습니다.\", fail: \"오류 알림\", error: \"저장하지 못했습니다\", retry: \"변경 사항은 유지됩니다. 다시 시도하세요.\", archive: \"초안 보관\", archived: \"초안이 보관되었습니다\", undo: \"실행 취소\", undone: \"보관을 취소했습니다\", idle: \"초안 사용 가능\", timed: \"자동 닫힘 알림\", quick: \"업데이트 알림\", region: \"알림\", close: \"알림 닫기\" },\n  ja: { save: \"成功通知\", success: \"変更を保存しました\", body: \"ローカル例です。サーバーへの送信は行いません。\", fail: \"エラー通知\", error: \"保存できませんでした\", retry: \"変更は保持されています。再試行してください。\", archive: \"下書きを保管\", archived: \"下書きを保管しました\", undo: \"元に戻す\", undone: \"保管を取り消しました\", idle: \"下書き利用可能\", timed: \"自動で閉じる通知\", quick: \"更新通知\", region: \"通知\", close: \"通知を閉じる\" },\n  zh: { save: \"成功通知\", success: \"更改已保存\", body: \"这是本地示例，未发送服务器请求。\", fail: \"错误通知\", error: \"保存失败\", retry: \"更改仍然保留，请重试。\", archive: \"归档草稿\", archived: \"草稿已归档\", undo: \"撤销\", undone: \"已撤销归档\", idle: \"草稿可用\", timed: \"自动关闭通知\", quick: \"更新通知\", region: \"通知\", close: \"关闭通知\" },\n};\n\nfunction ToastActions({ locale }: { locale: keyof typeof copy }) {\n  const text = copy[locale];\n  const manager = useToast();\n  const [status, setStatus] = React.useState<string>(text.idle);\n  return <div className=\"grid gap-4\"><div className=\"flex flex-wrap gap-3\">\n    <Button onClick={() => manager.add({ title: text.success, description: text.body, type: \"success\" })}>{text.save}</Button>\n    <Button onClick={() => manager.add({ title: text.error, description: text.retry, type: \"error\" })}>{text.fail}</Button>\n    <Button onClick={() => { setStatus(text.archived); const id = manager.add({ title: text.archived, description: text.body, actionProps: { children: text.undo, onClick: () => { setStatus(text.undone); manager.close(id); } } }); }}>{text.archive}</Button>\n    <Button onClick={() => manager.add({ title: text.quick, timeout: 1200 })}>{text.timed}</Button>\n  </div><p role=\"status\" className=\"text-sm text-[var(--muted-foreground)]\">{status}</p></div>;\n}\n\nexport default function ToastExample({ locale = \"en\" }: { locale?: keyof typeof copy }) {\n  // Keep examples available for inspection; the timed example overrides this.\n  return <ToastProvider timeout={0}><ToastActions locale={locale} /><Toaster label={copy[locale].region} closeLabel={copy[locale].close} /></ToastProvider>;\n}",

});

